static const z_t60_t _zag2660[] = {{ .data = "/* os.sleepMillis -- suspend the calling thread for ms milliseconds.\n   Restarts after EINTR so the full duration always elapses; Windows'\n   Sleep is not interrupted. */\n#include <time.h>\nstatic void z_os_sleepMillis(int64_t ms);\nstatic void z_os_sleepMillis(int64_t ms) {\n    if (ms <= 0) return;\n#if defined(_WIN32)\n    while (ms > 0) {\n        DWORD part = ms > 0x7fffffff ? 0x7fffffff : (DWORD)ms;\n        Sleep(part);\n        ms -= (int64_t)part;\n    }\n#else\n    struct timespec req;\n    req.tv_sec = (time_t)(ms / 1000);\n    req.tv_nsec = (long)(ms % 1000) * 1000000L;\n    while (nanosleep(&req, &req) != 0 && errno == EINTR) {\n    }\n#endif\n}", .size = 649 }};

